import sys


def solve():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    N = int(data[0])
    K = int(data[1])
    T = int(data[2])

    P = [int(x) for x in data[3 : 3 + N]]
    G = [int(x) for x in data[3 + N : 3 + 2 * N]]

    if K == N:
        print(sum(P))
        return

    inverted = False
    if K > N // 2:
        inverted = True
        K = N - K
        G = [1 - x for x in G]

    # Prefix sums of G
    c = [0] * (N + 1)
    for i in range(1, N + 1):
        c[i] = c[i - 1] + G[i - 1]

    # Precompute C(i, j) = sum_{k=1}^i |c_k - j|
    C = [[0] * (K + 1) for _ in range(N + 1)]
    for i in range(1, N + 1):
        c_i = c[i]
        C_prev = C[i - 1]
        C_curr = C[i]
        for j in range(K + 1):
            C_curr[j] = C_prev[j] + abs(c_i - j)

    INF = 10**15
    max_V = 9 * K

    # S[j][v] stores the minimal shifted time to select j elements with sum v
    S = [[INF] * (max_V + 1) for _ in range(K + 1)]
    S[0][0] = 0

    cur_max_v = [0] * (K + 1)

    for i in range(1, N + 1):
        p = P[i - 1]
        limit_j = min(i, K)
        C_prev = C[i - 1]

        for j in range(limit_j, 0, -1):
            delta = C_prev[j - 1] - C_prev[j]
            S_prev = S[j - 1]
            S_curr = S[j]
            new_v_max = cur_max_v[j - 1] + p
            if new_v_max > cur_max_v[j]:
                cur_max_v[j] = new_v_max

            for v in range(new_v_max, p - 1, -1):
                val = S_prev[v - p] + delta
                if val < S_curr[v]:
                    S_curr[v] = val

    final_C = C[N][K]

    if not inverted:
        ans = 0
        for v in range(cur_max_v[K] + 1):
            if S[K][v] + final_C <= T:
                if v > ans:
                    ans = v
        print(ans)
    else:
        total_P = sum(P)
        min_v = INF
        for v in range(cur_max_v[K] + 1):
            if S[K][v] + final_C <= T:
                if v < min_v:
                    min_v = v
        print(total_P - min_v)


if __name__ == "__main__":
    solve()
